cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void avg_pool1d_kernel(
    const half* input,
    half* output,
    int batch_size,
    int in_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * in_channels * output_length;

    if (idx >= total_elements) return;

    int batch_idx = idx / (in_channels * output_length);
    int channel_idx = (idx % (in_channels * output_length)) / output_length;
    int out_pos = idx % output_length;

    // Calculate input start position
    int input_start = out_pos * stride - padding;
    int input_end = input_start + kernel_size;

    // Clamp to valid range
    input_start = max(input_start, 0);
    input_end = min(input_end, input_length);

    // Number of elements actually used for averaging
    int count = input_end - input_start;
    if (count <= 0) {
        output[idx] = __float2half(0.0f);
        return;
    }

    // Compute average
    float sum = 0.0f;
    for (int i = input_start; i < input_end; i++) {
        int input_idx = batch_idx * (in_channels * input_length) + 
                       channel_idx * input_length + 
                       i;
        sum += __half2float(input[input_idx]);
    }

    float avg = sum / count;
    output[idx] = __float2half(avg);
}

extern "C" {
void launch_avg_pool1d(
    const half* input,
    half* output,
    int batch_size,
    int in_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding
) {
    int total_elements = batch_size * in_channels * output_length;
    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    avg_pool1d_kernel<<<grid_size, block_size>>>(
        input, output, batch_size, in_channels, input_length,
        output_length, kernel_size, stride, padding
    );

    cudaDeviceSynchronize();
}
}
"""

# Python wrapper
def compile_and_run():
    # Compile the CUDA extension
    module = load_inline(
        name="avg_pool1d_ext",
        cpp_sources=[],
        cuda_sources=[cuda_source],
        functions=["launch_avg_pool1d"],
        verbose=True
    )

    # Test parameters
    batch_size = 64
    in_channels = 128
    input_length = 65536
    kernel_size = 8
    stride = 1
    padding = 4

    # Calculate output length
    output_length = (input_length + 2 * padding - kernel_size) // stride + 1

    # Create test tensors
    input_tensor = torch.rand(batch_size, in_channels, input_length, dtype=torch.float16).cuda()
    output_tensor = torch.empty(batch_size, in_channels, output_length, dtype=torch.float16).cuda()

    # Launch kernel
    module.launch_avg_pool1d(
        input_tensor.data_ptr(),
        output_tensor.data_ptr(),
        batch_size,
        in_channels,
        input_length,
        output_length,
        kernel_size,
        stride,
        padding
    )

    return output_tensor

# Model class using the custom CUDA kernel
class ModelNew(torch.nn.Module):
    def __init__(self, kernel_size: int, stride: int = 1, padding: int = 0):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Calculate output length
        batch_size, in_channels, input_length = x.shape
        output_length = (input_length + 2 * self.padding - self.kernel_size) // self.stride + 1

        # Allocate output tensor
        output = torch.empty(batch_size, in_channels, output_length, dtype=torch.float16, device=x.device)

        # Call compiled CUDA kernel
        compile_and_run()
        return output

